const response = $input.first().json;
const content = response.choices[0].message.content;

const cleaned = content
  .replace(/^```json\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

const normalized = JSON.parse(cleaned);

// Use $('Get raw_story').item instead of .first()
// This gets the paired item for the current loop iteration
const prevItem = $('Get raw_story').item.json;

return [{
  json: {
    normalized_id: prevItem.raw_story_id || prevItem._id,
    raw_story_id: prevItem.raw_story_id || prevItem._id,
    catalog_id: prevItem.catalog_id,
    source_title: prevItem.source_title,
    story_url: prevItem.story_url,
    ...normalized,
    created_at: new Date().toISOString()
  }
}];

