=// ============================================================
// Stop and Error
// Surfaces the exact validation failure reason instead of a
// generic error, so failures are debuggable directly from the
// n8n execution log.
// ============================================================

const errors = $json.validation_errors || ['Unknown validation failure'];
const storyId = $json.story_id || 'unknown';
const title = $json.source_title || 'unknown';

throw new Error(
  `Artifact validation failed for story_id="${storyId}" ("${title}"): ` +
  errors.join(' | ')
);

