return [{
  json: {
    catalog_id: $json._id,
    editorial_status: 'ready_for_locale_profile_generation',
    updated_at: new Date().toISOString()
  }
}];

const data = $('Create normalized_stories').item.json;

const clean = (str) => (str || '')
  .replace(/\\/g, '')
  .replace(/"/g, "'")
  .replace(/\n/g, ' ')
  .replace(/\r/g, '')
  .trim();

const story_id = data.normalized_id;
if (!story_id) {
  throw new Error('normalized_id manquant sur Create normalized_stories — vérifie le node Firestore.');
}
const source_title = clean(data.source_title || '');

// Champs JSON stringifiés à parser
const safeParse = (str, fallback) => {
  try { return JSON.parse(str); } catch (e) { return fallback; }
};
const motifs = safeParse(data.motifs, []);
const characters = safeParse(data.characters, []);

// Reconstruction d'un texte source structuré à partir des champs normalisés
const charactersList = characters
  .map((c, i) => `${i + 1}. ${c.name} (${c.role}) — traits: ${(c.traits || []).join(', ')}`)
  .join('\n');

const source_text =
"SUMMARY: " + clean(data.canonical_summary) + "\n" +
"CORE CONFLICT: " + clean(data.core_conflict) + "\n" +
"CORE RESOLUTION: " + clean(data.core_resolution) + "\n" +
"MORAL: " + clean(data.moral) + "\n" +
"MOTIFS: " + motifs.join(', ') + "\n" +
"STORY FAMILY: " + clean(data.story_family) + "\n" +
"TARGET AGE: " + data.age_min + "-" + data.age_max + "\n" +
"KNOWN CHARACTERS (use these exact names, roles and order — do not rename or reorder):\n" + charactersList;

const schema = `{
  "story_id": "",
  "source_title": "",
  "story_type": "",
  "target_audience": "",
  "core_theme": [],
  "core_moral": [],
  "narrative_goal": "",
  "initial_state": {
    "situation": "",
    "protagonist_goal": "",
    "initial_conflict": ""
  },
  "story_structure": [
    {
      "sequence": 1,
      "phase": "",
      "narrative_function": "",
      "summary": "",
      "characters_involved": [],
      "key_events": [],
      "required_outcome": ""
    }
  ],
  "key_events": [
    {
      "event_id": "",
      "description": "",
      "narrative_function": "",
      "importance": "",
      "is_protected": true
    }
  ],
  "location_functions": [
    {
      "location_id": "",
      "narrative_function": "",
      "original_location": "",
      "adaptability": ""
    }
  ],
  "conflicts": [
    {
      "type": "",
      "description": "",
      "resolution": ""
    }
  ],
  "required_elements": [],
  "optional_elements": [],
  "adaptable_elements": [],
  "protected_elements": []
}`;

const prompt =
"You are a narrative structure analyst. You extract a STRUCTURAL blueprint from a children's story (ages " + data.age_min + "-" + data.age_max + "). " +
"This blueprint will later be used by a separate system to adapt the story to different cultures WITHOUT losing its narrative identity. " +
"You do not write prose. You do not adapt anything culturally. You only extract structure.\n\n" +

"ABSOLUTE RULES:\n" +
"1. Respond ONLY with valid JSON. No markdown code fences, no comments, no text before or after the JSON.\n" +
"2. Use EXACTLY the field names in the schema below, at every level. Never add, remove, or rename a field. Never return null — use \"\" or [] instead.\n" +
"3. Set \"story_id\" to exactly: " + story_id + "\n" +
"4. Set \"source_title\" to exactly: " + source_title + "\n" +
"5. Use the KNOWN CHARACTERS list below exactly as given (same names, same order) when assigning \"characters_involved\" ids: the 1st character = char_001, 2nd = char_002, etc.\n" +
"6. \"story_structure\" must cover the full narrative arc in order (sequence: 1, 2, 3, ...). Each \"phase\" must be one of: setup, inciting_incident, rising_action, climax, falling_action, resolution.\n" +
"7. \"key_events\" must use ids formatted as \"evt_001\", \"evt_002\", etc. Set \"is_protected\": true for any event whose removal or change would break the plot or the moral.\n" +
"8. \"location_functions\" must use ids formatted as \"loc_001\", \"loc_002\", etc. Describe the NARRATIVE FUNCTION of each location (e.g. \"place of safety\", \"place of danger/testing\"), not just its name. Set \"adaptability\" to exactly one of: \"fixed\", \"flexible\", \"fully_adaptable\".\n" +
"9. \"protected_elements\" must list every element (character names, key objects, the moral lesson, core relationships, the ending) that MUST remain unchanged in any cultural adaptation.\n" +
  "9b. HARD RULE: the names of all MAIN characters (protagonist, mentor, antagonist, and any character central to the plot) are part of the story's identity and must NEVER be translated, localized, or replaced — they must appear verbatim in \"protected_elements\", using the exact same spelling as in KNOWN CHARACTERS. Only background/minor character names may be adapted, and only if they are NOT listed in KNOWN CHARACTERS.\n" +
"10. \"adaptable_elements\" must list every element that CAN be freely changed for a target culture.\n" +
"11. \"required_elements\" = elements that must appear in every adaptation in some form. \"optional_elements\" = elements that can be dropped entirely.\n" +
"12. Keep the output CONCISE to avoid truncation: AT MOST 8 story_structure steps, AT MOST 8 key_events, AT MOST 5 location_functions, AT MOST 4 conflicts. Each 'summary'/'description' field must be ONE short sentence maximum.\n\n" +

"SCHEMA (follow exactly):\n" + schema + "\n\n" +
"SOURCE STORY TITLE: " + source_title + "\n" +
"SOURCE STORY DATA:\n" + source_text;

const fireworks_body = JSON.stringify({
  model: "accounts/fireworks/models/glm-5p3-flash",
  max_tokens: 8000,
  temperature: 0.2,
  reasoning_effort: "low",
  messages: [{ role: "user", content: prompt }]
});

return {
  story_id,
  source_title,
  characters,
  blueprint_prompt: prompt,
  fireworks_body
};

const data = $('Create normalized_stories').item.json;

const clean = (str) => (str || '')
  .replace(/\\/g, '')
  .replace(/"/g, "'")
  .replace(/\n/g, ' ')
  .replace(/\r/g, '')
  .trim();

const story_id = data.normalized_id;
if (!story_id) {
  throw new Error('normalized_id manquant sur Create normalized_stories — vérifie le node Firestore.');
}
const source_title = clean(data.source_title || '');

const safeParse = (str, fallback) => {
  try { return JSON.parse(str); } catch (e) { return fallback; }
};
const motifs = safeParse(data.motifs, []);
const characters = safeParse(data.characters, []);

const charactersList = characters
  .map((c, i) => `${i + 1}. ${c.name} (${c.role}) — traits: ${(c.traits || []).join(', ')}`)
  .join('\n');

const source_text =
"SUMMARY: " + clean(data.canonical_summary) + "\n" +
"CORE CONFLICT: " + clean(data.core_conflict) + "\n" +
"CORE RESOLUTION: " + clean(data.core_resolution) + "\n" +
"MORAL: " + clean(data.moral) + "\n" +
"MOTIFS: " + motifs.join(', ') + "\n" +
"KNOWN CHARACTERS (use these exact names, roles and order — do not rename, reorder, or drop any of them):\n" + charactersList;

const schema = `{
  "story_id": "",
  "source_title": "",
  "characters": [
    {
      "character_id": "",
      "name": "",
      "role": "",
      "description": "",
      "traits": [],
      "goals": [],
      "motivations": [],
      "important_attributes": {},
      "protected_attributes": []
    }
  ],
  "relationships": [
    {
      "source_character_id": "",
      "target_character_id": "",
      "relationship_type": "",
      "description": "",
      "is_protected": true
    }
  ],
  "important_entities": [
    {
      "entity_id": "",
      "name": "",
      "type": "",
      "description": "",
      "narrative_role": ""
    }
  ],
  "world_rules": [
    {
      "rule": "",
      "is_protected": true
    }
  ],
  "continuity_constraints": [
    ""
  ]
}`;

const prompt =
"You are a canon-keeper extracting the Story Bible from a children's story (ages " + data.age_min + "-" + data.age_max + "). " +
"This Story Bible will later be used, together with a separate Story Blueprint for the SAME story_id, by a cultural adaptation system. " +
"You do not write prose. You do not adapt anything culturally. You only extract canon.\n\n" +

"ABSOLUTE RULES:\n" +
"1. Respond ONLY with valid JSON. No markdown code fences, no comments, no text before or after the JSON.\n" +
"2. Use EXACTLY the field names in the schema below, at every level. Never add, remove, or rename a field. Never return null — use \"\", [], or {} instead.\n" +
"3. Set \"story_id\" to exactly: " + story_id + "\n" +
"4. Set \"source_title\" to exactly: " + source_title + "\n" +
"5. The \"characters\" array MUST contain exactly the characters listed in KNOWN CHARACTERS below, in the SAME order, with the SAME names and roles. Assign ids char_001, char_002, etc. in that order. Do not add characters not in this list. Do not omit any of them.\n" +
"6. Use the \"traits\" already given in KNOWN CHARACTERS as a base — you may add 1-2 more if clearly implied by the story, but do not contradict them.\n" +
"7. \"protected_attributes\" is a FIXED LABEL LIST, not values. For every character, it must be an array containing ONLY a subset of these exact strings: \"name\", \"core personality trait\", \"core goal\", \"defining physical or moral trait\". NEVER put an actual value there (e.g. do NOT write \"Simba\" or \"brave\" or \"golden mane\" inside protected_attributes — those belong in \"name\", \"traits\", and \"important_attributes\" instead). Example for a character named Simba with trait 'brave': \"protected_attributes\": [\"name\", \"core personality trait\", \"core goal\"].\n" +
  "7b. HARD RULE: for every character listed in KNOWN CHARACTERS, \"protected_attributes\" MUST include \"name\" — with no exception. Main character names carry the story's identity across all cultural adaptations and must never be localized, translated, or replaced with a culturally equivalent name.\n" +
"8. \"important_attributes\" is a flat key-value object for other notable attributes (age, occupation, appearance) that CAN be adapted.\n" +
"9. \"relationships\" must reference character_id values from the \"characters\" array only. Set \"is_protected\": true for any relationship whose nature must not change (parent/child, mentor/student, hero/villain).\n" +
"10. \"important_entities\" covers non-character plot elements (objects, key locations as narrative entities, institutions). Use ids formatted as \"ent_001\", etc.\n" +
"11. \"world_rules\" = the internal logic of the story's world that must stay consistent across any adaptation.\n" +
"12. \"continuity_constraints\" = plain-language statements a rewritten version must respect.\n" +
"13. Keep the output CONCISE to avoid truncation: AT MOST 6 relationships, AT MOST 5 important_entities, AT MOST 5 world_rules, AT MOST 5 continuity_constraints. Each 'description' field must be ONE short sentence maximum.\n\n" +

"SCHEMA (follow exactly):\n" + schema + "\n\n" +
"SOURCE STORY TITLE: " + source_title + "\n" +
"SOURCE STORY DATA:\n" + source_text;

const fireworks_body = JSON.stringify({
  model: "accounts/fireworks/models/glm-5p3-flash",
  max_tokens: 8000,
  temperature: 0.2,
  reasoning_effort: "low",
  messages: [{ role: "user", content: prompt }]
});

return {
  story_id,
  source_title,
  characters,
  bible_prompt: prompt,
  fireworks_body
};

// ============================================================
// Validate Artifacts
// Combines the Bible and Blueprint produced in parallel for the
// SAME loop iteration, cross-checks their consistency, and
// flags the result with _valid + validation_errors.
// Mode: Run Once for All Items (required for $input.all()).
// ============================================================

const items = $input.all();

// Identify each branch by its distinguishing key rather than by
// array position, since parallel branches are not guaranteed to
// arrive in a fixed order.
const bibleWrap = items.find(i => i.json.bible)?.json;
const blueprintWrap = items.find(i => i.json.blueprint)?.json;

const errors = [];

const bib = bibleWrap?.bible;
const bp = blueprintWrap?.blueprint;

// --- Presence checks ---
if (!bib) errors.push('Bible is missing for this iteration');
if (!bp) errors.push('Blueprint is missing for this iteration');

// --- Cross-branch consistency checks (only if both exist) ---
if (bib && bp) {

  // Guard against loop desynchronization: both branches must
  // belong to the exact same story.
  if (bib.story_id !== bp.story_id) {
    errors.push(
      `story_id mismatch: bible.story_id="${bib.story_id}" vs blueprint.story_id="${bp.story_id}" ` +
      `(possible loop desynchronization between parallel branches)`
    );
  }

  // --- Required Bible fields ---
  if (!Array.isArray(bib.characters) || bib.characters.length === 0) {
    errors.push('bible.characters is empty or missing');
  }
  if (!Array.isArray(bib.world_rules) || bib.world_rules.length === 0) {
    errors.push('bible.world_rules is empty or missing');
  }

  // --- Required Blueprint fields ---
  if (!Array.isArray(bp.story_structure) || bp.story_structure.length === 0) {
    errors.push('blueprint.story_structure is empty or missing');
  }
  if (!Array.isArray(bp.key_events) || bp.key_events.length === 0) {
    errors.push('blueprint.key_events is empty or missing');
  }
  if (!Array.isArray(bp.protected_elements) || bp.protected_elements.length === 0) {
    errors.push('blueprint.protected_elements is empty or missing');
  }

  // --- Cross-reference check: every character_id used in the
  // Blueprint's story_structure must exist in the Bible's
  // characters array. This guarantees the two artifacts stay
  // usable together during later cultural adaptation. ---
  if (Array.isArray(bib.characters) && Array.isArray(bp.story_structure)) {
    const bibleIds = new Set(bib.characters.map(c => c.character_id));
    const usedInBlueprint = new Set();
    bp.story_structure.forEach(step => {
      (step.characters_involved || []).forEach(id => usedInBlueprint.add(id));
    });
    const missingInBible = [...usedInBlueprint].filter(id => !bibleIds.has(id));
    if (missingInBible.length > 0) {
      errors.push(
        'character_id(s) referenced in blueprint.story_structure but missing from bible.characters: ' +
        missingInBible.join(', ')
      );
    }
  }
}

const _valid = errors.length === 0;

return [{
  json: {
    story_id: bib?.story_id || bp?.story_id || null,
    source_title: bibleWrap?.source_title || blueprintWrap?.source_title || null,
    blueprint: bp || null,
    bible: bib || null,
    _valid,
    validation_errors: errors
  }
}];

const raw = $input.item.json;
const context = $('Build Bible Prompt').item.json;

const rawText = raw.choices?.[0]?.message?.content || raw.text || '';

const firstBrace = rawText.indexOf('{');
const lastBrace = rawText.lastIndexOf('}');
if (firstBrace === -1 || lastBrace === -1) {
  throw new Error('Bible LLM response contains no JSON object: ' + rawText.slice(0, 300));
}

let bible;
try {
  bible = JSON.parse(rawText.slice(firstBrace, lastBrace + 1));
} catch (e) {
  throw new Error('Bible JSON parse failed: ' + e.message);
}

bible.story_id = context.story_id;
bible.source_title = context.source_title;

const arrayFields = ['characters', 'relationships', 'important_entities', 'world_rules', 'continuity_constraints'];
for (const field of arrayFields) {
  if (!Array.isArray(bible[field])) bible[field] = [];
}
const ALLOWED_PROTECTED_LABELS = new Set([
  'name',
  'core personality trait',
  'core goal',
  'defining physical or moral trait'
]);

if (Array.isArray(bible.characters)) {
  bible.characters.forEach(c => {
    if (Array.isArray(c.protected_attributes)) {
      c.protected_attributes = c.protected_attributes.filter(a => ALLOWED_PROTECTED_LABELS.has(a));
    } else {
      c.protected_attributes = [];
    }
  });
}

return {
  story_id: context.story_id,
  source_title: context.source_title,
  bible
};

const raw = $input.item.json;
const context = $('Build Blueprint Prompt').item.json;

// Fireworks renvoie choices[0].message.content
const rawText = raw.choices?.[0]?.message?.content || raw.text || '';

// Extraction robuste : on prend du premier { au dernier }
const firstBrace = rawText.indexOf('{');
const lastBrace = rawText.lastIndexOf('}');
if (firstBrace === -1 || lastBrace === -1) {
  throw new Error('Blueprint LLM response contains no JSON object: ' + rawText.slice(0, 300));
}

let blueprint;
try {
  blueprint = JSON.parse(rawText.slice(firstBrace, lastBrace + 1));
} catch (e) {
  throw new Error('Blueprint JSON parse failed: ' + e.message);
}

// Sécurise les identifiants même si le LLM les a mal recopiés
blueprint.story_id = context.story_id;
blueprint.source_title = context.source_title;

// Garantit la présence de tous les tableaux du schéma (évite les undefined en aval)
const arrayFields = [
  'core_theme', 'core_moral', 'story_structure', 'key_events',
  'location_functions', 'conflicts', 'required_elements',
  'optional_elements', 'adaptable_elements', 'protected_elements'
];
for (const field of arrayFields) {
  if (!Array.isArray(blueprint[field])) blueprint[field] = [];
}
if (typeof blueprint.initial_state !== 'object' || blueprint.initial_state === null) {
  blueprint.initial_state = { situation: '', protagonist_goal: '', initial_conflict: '' };
}

return {
  story_id: context.story_id,
  source_title: context.source_title,
  blueprint
};

const data = $json;

if (!data.blueprint || typeof data.blueprint !== 'object') {
  throw new Error('blueprint is missing or not an object at Prepare Artifacts Fields: ' + JSON.stringify(data.blueprint));
}
if (!data.bible || typeof data.bible !== 'object') {
  throw new Error('bible is missing or not an object at Prepare Artifacts Fields: ' + JSON.stringify(data.bible));
}

// Firestore (node n8n) échoue à inférer le type d'un tableau vide []
// et envoie par erreur un integerValue au lieu d'un arrayValue.
// Fix : remplacer récursivement chaque [] par null avant l'écriture.
// (null est correctement typé nullValue par Firestore, sans ambiguïté)
function sanitizeEmptyArrays(value) {
  if (Array.isArray(value)) {
    if (value.length === 0) return null;
    return value.map(sanitizeEmptyArrays);
  }
  if (value && typeof value === 'object') {
    const out = {};
    for (const key of Object.keys(value)) {
      out[key] = sanitizeEmptyArrays(value[key]);
    }
    return out;
  }
  return value;
}

const created_at = new Date().toISOString();

return [{
  json: {
    story_id: data.story_id,
    source_title: data.source_title,
    blueprint: sanitizeEmptyArrays(data.blueprint),
    bible: sanitizeEmptyArrays(data.bible),
    status: 'artifact_ready',
    created_at
  }
}];
